window.DOSIK=window.DOSIK||{};DOSIK["yc_abnormal2"]={"1":[{"t":"vs","title":"이상행동의 모형","cols":[{"name":"생물학적 모형","items":["이상행동을 유전적 요인과 뇌의 구조적 결함 등으로 인한 질병으로 본다"]},{"name":"행동주의 모형","items":["이상행동을 조건형성을 통해 설명한다","이상행동을 잘못된 학습의 결과로 본다","이상행동은 주로 고전적 조건형성, 조작적 조건형성, 사회적 모델링의 3가지 학습원리로 설명된다","치료에는 체계적 둔감법이 있다"]},{"name":"정신분석 모형","items":["오이디푸스 갈등이 나타나는 발달단계는 남근기이다"]}]},{"t":"def","term":"행동주의 모형의 가정","text":"무의식적 욕구나 갈등은 가정하지 않는다"}],"2":[{"t":"table","title":"분류체계의 이점","head":["이점","내용"],"rows":[["예후와 치료","예후와 치료의 효과성을 예측하는데 도움이 된다"],["유사성과 차이점","심리장애의 유사성과 차이점을 구별하는데 도움을 준다"],["의사소통","정신건강 전문가 사이에 효과적인 의사소통을 가능하게 한다 · 분류체계는 정신장애를 치료하는 의사나 연구자들 간 소통에 도움을 주어 · 불필요한 혼란과 모호함을 감소시켜 준다"],["연구와 이론","정신장애에 대한 과학적 연구와 이론개발을 위한 기초를 제공한다"],["공통 용어","상담자들과 연구자들이 일관성 있게 공통적인 용어를 사용할 수 있다"],["지식 정리","축적된 연구결과와 임상적 지식을 체계적으로 정리 및 전달할 수 있다"],["공통 특성","정신장애의 공통적 특성과 원인에 대한 연구가 가능해진다"]]},{"t":"tree","title":"진단과 평가","root":"이상행동의 평가","branches":[["DSM-5","DSM-5에서 다축체계를 폐기하였다"],["정신상태검사","정신상태검사에서 환자의 외모와 외현적 행동도 평가한다"],["평가목적","적절한 평가방법과 절차를 계획하기 전에 평가목적을 명료화한다"]]}],"3":[{"t":"tree","title":"주의력결핍 과잉행동장애의 진단기준","root":"주의력결핍 과잉행동장애","branches":[["증상 환경","몇 가지의 부주의 또는 과잉행동-충동성 증상이 두 가지 또는 그 이상의 환경에서 존재한다 · 행동문제가 2가지 이상의 다른 환경에서 나타난다"],["발병 시기","부주의 또는 과잉행동/충동성 증상 중의 일부는 12세 이전에 나타난다 · 몇가지 부주의 또는 과잉행동-충동성 증상은 12세 이전에 나타난다"],["증상 수","후기 청소년이나 성인의 경우에 세부 유형의 증상이 5개이어도 해당된다"],["지속 기간","세부 유형의 증상은 각각 최소 6개 영역에서 6개월 동안 부정적 영향이 지속된다"]]},{"t":"tree","title":"주의력결핍 과잉행동장애의 특징","root":"주의력결핍 과잉행동장애","branches":[["공존장애","주의력결핍 과잉행동장애가 있는 아동은 품행장애 등 공존장애를 가지고 있는 경우가 있다"],["성인기","성인기까지 지속되어 사회적ㆍ학업적ㆍ직업적 손상을 야기할 수 있다 · 부주의, 충동성, 계획성 부족은 성인기까지 지속되는 경향이 있다"],["성별","여성은 남성에 비해 주로 부주의 증상을 보인다"],["치료약물","리탈린(Ritalin)과 같은 중추신경자극제가 치료약물로 사용된다 · 리탈린(Ritalin)과 같은 중추신경계자극제가 치료약물로 사용된다"]]}],"4":[{"t":"tree","title":"망상장애","root":"망상장애","branches":[["하위유형","과대형, 피해형, 질투형, 신체형 등이 있다"],["지속 기간","1개월 이상의 지속 기간을 가진 한 가지 혹은 그 이상의 망상이 존재한다"],["기분 삽화","조증이나 주요우울 삽화가 일어난다면 망상 지속 기간에 비해 상대적으로 짧다"],["기능","망상의 영향이나 파생 결과를 제외한다면 기능이 현저하게 손상되지 않고 행동이 뚜렷하게 이상하거나 괴이하지 않다"]]},{"t":"tree","title":"조현병 스펙트럼의 장애","root":"조현병 스펙트럼 및 기타 정신병적 장애","branches":[["양성증상","와해된 언어는 양성증상이다"],["조현형 성격장애","조현병 스펙트럼장애로 분류된다"],["조현정동장애","주요 기분(주요우울 또는 조증)삽화 없이 존재하는 2주 이상의 망상이나 환각이 있다"],["단기 정신병적 장애","심각도는 지난 7일중 정신병의 일차 증상 각각에 대하여 가장 심한 정도를 5점 척도로 평가한다"]]}],"5":[{"t":"tree","title":"양극성 및 관련장애","root":"양극성 및 관련장애","branches":[["제Ⅰ형 양극성장애","진단하기 위해서는 조증 삽화 진단기준이 충족되어야 한다"],["순환성장애","경미한 형태의 조증 증상과 우울 증상이 · 2년 이상 번갈아 나타나는 만성적인 기분장애이다"],["분류","우울장애와 다른 범주로 분류되어 있다"],["하위 유형","제Ⅰ형 양극성 장애, 제Ⅱ형 양극성 장애, 순환성장애가 있다"],["발병","양극성 장애는 모든 연령대에서 발병할 수 있다"]]}],"6":[{"t":"table","title":"우울장애의 종류","head":["장애","특징"],"rows":[["월경전불쾌감장애","월경이 시작되기 1주 전에 여러 가지 우울증상이 나타난다"],["주요우울장애","우울한 기분 또는 흥미나 즐거움의 상실 증상이 필수적이다"],["지속성 우울장애","적어도 2년 동안 하루의 대부분 우울한 기분이 있으며, 증상 없는 기간이 2개월 이상 지속되지 않는다"],["파괴적 기분조절부전장애","주요 특징은 만성적인 고도의 지속적 과민성이다"]]},{"t":"def","term":"우울장애의 발병","text":"어떤 연령대에서도 발병할 수 있지만, 아동기에 비해 청소년기에 발병가능성이 높아진다"}],"7":[{"t":"tree","title":"공황장애","root":"공황장애","branches":[["공황발작","반복적으로 예상하지 못한 공황발작이 일어난다"],["인지이론","공황장애 3요인 인지이론은 공황장애가 불안 민감성, 파국적 오해석, 공황적 자기 효능감에 의해서 유발된다고 본다"],["신경생물학","신경생물학적 관점에서는 청반핵과 노르에피네프린이 공황장애와 관련되어 있다고 본다"],["치료","대표적인 치료방법으로 공황통제치료(panic control treatment)가 있다"]]},{"t":"tree","title":"범불안장애","root":"범불안장애","branches":[["핵심","핵심적 특징은 수많은 사건이나 활동에 대한 과도한 불안과 걱정이다"],["정도","불안과 걱정의 정도, 기간, 빈도는 예상되는 사건이 미치는 실제 영향에 비해 과도하다"],["기간","일상생활에 대해서 지나치게 불안해하거나 걱정하는 기간이 최소 6개월 이상이다"],["걱정 대상","직업이나 건강, 재정, 사소한 문제와 같은 일상생활 환경에 대해 걱정한다"]]},{"t":"tree","title":"사회불안장애","root":"사회불안장애","branches":[["회피","다른 사람들과 상호작용하는 사회적 상황을 두려워하여 회피하는 경우를 말한다"],["공포와 불안","하나 이상의 사회적 상황에서 공포와 불안을 보인다"],["평가","타인의 부정적 평가를 두려워한다"],["기간","전형적으로 공포, 불안, 회피는 6개월 이상 지속되어야 한다"]]}],"8":[{"t":"tree","title":"강박장애","root":"강박 및 관련장애","branches":[["강박사고와 강박행동","강박사고나 강박행동은 시간을 소모하게 만든다"],["정의","원하지 않은 불쾌한 생각이 자꾸 떠올라 · 그것을 제거하기 위한 행동을 반복하게 되는 장애이다"],["발병 연령","일반적으로 발병 연령은 남성이 여성보다 더 빠르다"],["치료","심리적 치료방법으로 노출 및 반응방지법이 효과적이라고 알려져 있다"]]},{"t":"tree","title":"신체이형장애","root":"신체 결함에 대한 집착","branches":[["집착","하나 이상의 신체 결함에 과도하게 집착한다"],["얼굴","자기 얼굴의 미묘한 비대칭성을 발견한다"],["성형수술","성형수술을 원하는 경향이 있다"],["학대와 무시","타인의 정서적 학대 및 무시와는 무관하다"]]}],"9":[{"t":"table","title":"외상 및 스트레스 관련장애","head":["장애","특징"],"rows":[["반응성 애착장애","아동이 보호자로 추정되는 사람과 애착이 없거나 명백하게 미발달되어 있다"],["탈억제성 사회적 유대감 장애","양육자와의 애착 외상을 경험한 아동이 낯선 사람을 대상으로 문화적으로 부적절하고 과도하게 친숙한 행동을 보인다"],["적응장애","인식 가능한 스트레스 요인에 대한 반응으로 감정 또는 행동증상이 스트레스 요인이 시작된 지 3개월 이내에 발달한다 · 스트레스 사건 후 정서적ㆍ행동적 문제들이 3개월 이내에 발생하고, 그 스트레스 요인이 사라지면 6개월 이내로 회복함"],["급성 스트레스 장애","외상성 사건에 노출된 뒤 3일 이상 1개월 이내로 증상이 지속됨"],["외상후 스트레스장애","충격적인 외상사건을 경험한 후 그 후유증으로 1개월 이상 반복적이고 불수의적이며 침습적으로 외상사건이 떠오르는 고통스러운 증상을 경험한다 · 외상성 사건을 경험한 후, 그 후유증으로 1개월 이상 다양한 부적응적 증상들을 재경험함"]]}],"11":[{"t":"tree","title":"신체증상 및 관련장애","root":"신체증상 및 관련장애","branches":[["삼키기","음식을 삼키기 어려운 증상도 포함된다"],["질병 몰두","심각한 질병에 걸려 있거나 걸리는 것에 대해 몰두한다"],["유병률","유병률은 남성과 여성이 비슷하다"],["세분","의학적 진료추구형과 진료회피형으로 세분된다"],["의학적 상태","의학적 상태가 나타나도 질병에 대한 몰두가 과도하거나 부적절하다"]]}],"12":[{"t":"tree","title":"급식 및 섭식장애","root":"급식 및 섭식장애","branches":[["섭취행동","섭취행동이 사회적 관습, 혹은 문화적 지지를 받지 못한다"],["되새김장애","되새김장애는 청소년기에도 발병할 수 있다"]]}],"13":[{"t":"tree","title":"악몽장애","root":"수면-각성장애","branches":[["심각도","악몽이 발생한 빈도에 따라 심각도를 구분한다"],["지남력","불쾌한 꿈에서 깨면 빠르게 지남력을 회복한다"],["유병률","청소년기 후기나 성인기 초기에 유병률이 가장 높다"],["내용","주로 생존이나 안전을 위협하는 내용과 관련된 악몽을 꾼다"]]}],"14":[{"t":"tree","title":"성별 불쾌감","root":"성별 불쾌감","branches":[["분류","성기능부전, 성도착장애 및 성별 불쾌감"],["기간","최소 6개월 기간으로 진단기준의 증상들이 나타나야 한다"],["복장","남자 아이 또는 여자 아이는 이성(반대 성)의 · 복장을 선호하고 착장하기를 선호한다"],["해부학적 성별","자신의 해부학적 성별에 대해서는 강한 혐오를 가진다"],["놀이","가상 놀이 또는 환상 놀이에서 이성(반대 성)의 역할을 선호한다"]]}],"15":[{"t":"tree","title":"적대적 반항장애","root":"적대적 반항장애","branches":[["분류","파괴적, 충동조절 및 품행장애"],["논쟁","아동이나 청소년의 경우 성인과 잦은 논쟁을 한다"],["권위자","권위자의 요구, 규칙을 무시하거나 거부하는 행동을 적극적으로 자주 한다"],["남탓","자신의 실수나 잘못된 행동을 자주 남의 탓으로 돌린다"],["분노","자주 화를 내고 크게 분개한다"]]},{"t":"tree","title":"품행장애","root":"품행장애","branches":[["동물","동물에게 신체적으로 잔인하게 대한다"],["재산 파괴","다른 사람의 집, 건물 또는 자동차를 망가뜨린다"],["방화","심각한 손상을 입히려는 의도로 고의적으로 불을 지른다"],["귀가","부모의 제지에도 불구하고 13세 이전부터 · 자주 밤늦게까지 집에 들어오지 않는다"]]},{"t":"tree","title":"충동조절장애","root":"충동조절장애","branches":[["긴장감","훔치기 직전에 고조되는 긴장감이 나타난다"],["병적 방화(방화광)","방화를 하기 위해 사전에 충분한 준비를 한다"]]}],"17":[{"t":"tree","title":"경도 신경인지장애","root":"신경인지장애","branches":[["원인","장애의 원인은 주요 신경인지장애와 동일하다"],["신경심리검사","표준화된 신경심리검사에 의해서 경도의 인지 손상이 입증될 수 있다"],["인식","경도의 인지 저하는 자신 또는 잘 아는 지인에 의해 인식될 수 있다"],["인지 영역","하나 이상의 인지 영역에서 이전에 비해 경도의 저하가 나타난다"]]}],"18":[{"t":"table","title":"성격장애의 특징","head":["항목","내용"],"rows":[["관심의 초점","자신이 관심의 초점이 되지 못하는 상황에서 불편감을 느낀다"],["유혹적 태도","다른 사람과의 관계에서 흔히 상황에 어울리지 않게 성적으로 유혹적이거나 도발적이다"],["언어","지나치게 인상적이고 세밀함이 결여된 형태의 언어를 사용한다"],["지인","타인과의 관계를 실제보다 더 가깝다고 생각해 거의 모든 지인을 친한 친구라고 표현한다"],["칭찬·비난","타인의 칭찬이나 비난에 무관심하다"],["활동","대부분 혼자서 하는 활동을 선택한다"],["정서","정서적으로 냉담하고 감정표현이 제한되어 있다"],["아동기·청소년기","아동기나 청소년기에 외톨이, 학습부진 등의 양상을 보인다"],["능력","자신의 능력을 스스로 과소평가한다"],["신념","사람들이 악의적이고 기만적이라는 신념을 가진다"],["의심","충분한 근거 없이 타인이 자신을 착취하고 해를 끼친다고 의심한다"],["치료","치료에서는 상담자가 방어적으로 반응하기보다 솔직하고 일관성 있는 태도로 신뢰감을 주는 것이 중요하다"]]}]};
