(window.TNQ=window.TNQ||[]).push({"terms":{"조건형성":{"d":"자극과 반응이 반복해서 짝지어지며 행동이 학습되는 과정입니다.","r":["체계적 둔감법"]},"체계적 둔감법":{"d":"이완 상태에서 약한 불안 자극부터 차례로 노출해 불안 반응을 줄이는 행동치료 기법입니다.","r":["조건형성"]},"사회적 모델링":{"d":"다른 사람의 행동을 관찰하고 따라 하며 새 행동을 배우는 학습 원리입니다.","r":[]},"오이디푸스 갈등":{"d":"남자 아이가 어머니에게 애정을 느끼고 아버지를 경쟁자로 여기는 프로이트의 개념입니다.","r":["남근기"]},"남근기":{"d":"프로이트 발달단계 중 성기에 관심이 모이는 시기로 오이디푸스 갈등이 나타납니다.","r":["오이디푸스 갈등"]},"예후":{"d":"질병이나 장애가 앞으로 어떻게 진행되고 회복될지에 대한 전망입니다.","r":[]},"다축체계":{"d":"장애와 신체 상태, 심리사회적 문제를 여러 축으로 나누어 평가하던 DSM의 진단 방식입니다.","r":[]},"정신상태검사":{"d":"면담 중 외모, 행동, 사고, 기분, 인지 상태를 관찰해 평가하는 검사입니다.","r":[]},"중추신경자극제":{"d":"뇌의 각성과 주의를 높이는 약물로 주의력결핍 과잉행동장애의 치료에 쓰입니다.","r":[]},"공황발작":{"d":"극심한 공포와 신체 증상이 갑자기 치솟아 몇 분 안에 절정에 이르는 발작입니다.","r":["파국적 오해석"]},"파국적 오해석":{"d":"신체 감각을 곧 죽거나 미칠 징조라고 재앙처럼 잘못 해석하는 인지 오류입니다.","r":["공황발작"]},"청반핵":{"d":"노르에피네프린을 내보내는 뇌간의 핵으로 불안과 공황 반응에 관여합니다.","r":["노르에피네프린"]},"노르에피네프린":{"d":"각성과 스트레스 반응에 관여하는 신경전달물질입니다.","r":["청반핵"]},"공황통제치료":{"d":"신체 감각 노출과 인지 재구성으로 공황발작에 대한 공포를 줄이는 인지행동치료입니다.","r":["공황발작"]},"강박사고":{"d":"원치 않는데도 반복해서 떠올라 불안을 일으키는 생각이나 충동입니다.","r":["강박행동"]},"강박행동":{"d":"강박사고로 생긴 불안을 줄이려고 반복하는 행동이나 마음속 행위입니다.","r":["강박사고"]},"노출 및 반응방지법":{"d":"불안 자극에 직면하게 하되 강박행동을 하지 못하게 막아 불안이 가라앉는 것을 경험시킵니다.","r":["강박행동"]},"지남력":{"d":"시간, 장소, 사람 등 자신이 놓인 상황을 올바르게 아는 능력입니다.","r":[]},"신경심리검사":{"d":"기억, 주의, 언어 같은 인지 기능을 표준화된 과제로 측정하는 검사입니다.","r":[]},"되새김장애":{"d":"삼킨 음식을 반복해서 입으로 되올려 씹거나 뱉는 급식 및 섭식장애입니다.","r":[]}},"notes":{"1개월 이상의 지속 기간을 가진 한 가지 혹은 그 이상의 망상이 존재한다":"망상이 한 달 넘게 이어져야 망상장애로 진단하는 기간 기준입니다.","2년 이상 번갈아 나타나는 만성적인 기분장애이다":"가벼운 기분 변동이 2년 넘게 오르내리며 이어져야 순환성장애에 해당합니다.","DSM-5에서 다축체계를 폐기하였다":"DSM-5는 축을 나누던 진단 방식을 없애고 장애와 상태를 한 목록에서 함께 기록합니다.","가상 놀이 또는 환상 놀이에서 이성(반대 성)의 역할을 선호한다":"소꿉놀이 같은 상상 놀이에서도 반대 성의 역할을 계속 고르는 것이 아동의 기준입니다.","강박사고나 강박행동은 시간을 소모하게 만든다":"하루에 많은 시간을 쓰게 되어 일상 생활에 지장을 주는 것이 진단 기준의 하나입니다.","경도의 인지 저하는 자신 또는 잘 아는 지인에 의해 인식될 수 있다":"본인이나 가까운 사람이 이전보다 인지가 떨어졌음을 알아차리는 것이 진단 기준입니다.","경미한 형태의 조증 증상과 우울 증상이":"순환성장애는 정도가 가벼운 조증 증상과 우울 증상이 함께 나타나는 만성 기분장애의 앞부분 설명입니다.","공황장애 3요인 인지이론은 공황장애가 불안 민감성, 파국적 오해석, 공황적 자기 효능감에 의해서 유발된다고 본다":"불안 증상에 민감하고 그것을 재앙으로 해석하며 대처할 자신이 없을 때 공황이 생긴다는 설명입니다.","과대형, 피해형, 질투형, 신체형 등이 있다":"망상장애는 망상의 주제에 따라 자신이 대단하다고 믿는 과대형 등으로 하위 유형을 나눕니다.","권위자의 요구, 규칙을 무시하거나 거부하는 행동을 적극적으로 자주 한다":"부모나 교사의 요구와 규칙에 일부러 따르지 않는 반항이 반복됩니다.","그것을 제거하기 위한 행동을 반복하게 되는 장애이다":"떠오르는 생각이 주는 불안을 없애려고 정해진 행동을 되풀이하는 것이 강박장애입니다.","남자 아이 또는 여자 아이는 이성(반대 성)의":"아동의 성별 불쾌감 기준 중 이성의 복장 선호를 설명하는 문장의 앞부분입니다.","다른 사람과의 관계에서 흔히 상황에 어울리지 않게 성적으로 유혹적이거나 도발적이다":"연극성 성격장애는 주목을 끌려고 때와 장소에 맞지 않는 유혹적 행동을 보입니다.","다른 사람들과 상호작용하는 사회적 상황을 두려워하여 회피하는 경우를 말한다":"사회불안장애는 사람들과 어울리는 자리가 두려워 그런 상황을 피하는 장애입니다.","다른 사람의 집, 건물 또는 자동차를 망가뜨린다":"남의 재산을 부수는 행동은 품행장애의 재산 파괴 기준에 해당합니다.","대부분 혼자서 하는 활동을 선택한다":"관계에 흥미가 적어 어울리는 활동보다 혼자 하는 활동을 고르는 편입니다.","대표적인 치료방법으로 공황통제치료(panic control treatment)가 있다":"공황 때 느끼는 신체 감각에 일부러 노출하고 해석을 바꾸어 공포를 낮추는 치료법입니다.","동물에게 신체적으로 잔인하게 대한다":"사람이나 동물에게 해를 입히는 공격성은 품행장애의 진단 기준에 속합니다.","되새김장애는 청소년기에도 발병할 수 있다":"되새김장애는 영아기에 흔하지만 청소년기에도 나타날 수 있습니다.","리탈린(Ritalin)과 같은 중추신경계자극제가 치료약물로 사용된다":"리탈린은 중추신경계를 자극해 주의와 충동 조절을 개선하는 치료약물입니다.","리탈린(Ritalin)과 같은 중추신경자극제가 치료약물로 사용된다":"각성을 높이는 약물이 오히려 주의 집중을 돕기 때문에 치료에 쓰입니다.","망상의 영향이나 파생 결과를 제외한다면 기능이 현저하게 손상되지 않고 행동이 뚜렷하게 이상하거나 괴이하지 않다":"망상과 관련된 부분 밖에서는 일상 기능이 유지되고 행동도 기이하지 않다는 점이 조현병과 다릅니다.","몇가지 부주의 또는 과잉행동-충동성 증상은 12세 이전에 나타난다":"성인에게 진단할 때도 어린 시절인 12세 이전에 증상이 있었는지를 확인합니다.","몇 가지의 부주의 또는 과잉행동-충동성 증상이 두 가지 또는 그 이상의 환경에서 존재한다":"집과 학교처럼 둘 이상의 장소에서 증상이 나타나야 주의력결핍 과잉행동장애로 봅니다.","무의식적 욕구나 갈등은 가정하지 않는다":"행동주의는 눈에 보이는 행동과 학습만 다루고 정신분석처럼 무의식을 가정하지 않습니다.","반복적으로 예상하지 못한 공황발작이 일어난다":"공황장애는 뚜렷한 계기 없이 갑작스럽게 오는 공황발작이 되풀이되는 장애입니다.","복장을 선호하고 착장하기를 선호한다":"자신의 성별과 다른 성의 옷을 입는 것을 강하게 좋아하는 것이 아동 진단 기준의 하나입니다.","부모의 제지에도 불구하고 13세 이전부터":"부모가 말려도 밤늦게 귀가하지 않는 행동이 13세 이전에 시작되었는지 묻는 문장의 앞부분입니다.","부주의, 충동성, 계획성 부족은 성인기까지 지속되는 경향이 있다":"과잉행동은 나이 들며 줄어도 부주의와 충동성과 계획성 부족은 성인기까지 남기 쉽습니다.","부주의 또는 과잉행동/충동성 증상 중의 일부는 12세 이전에 나타난다":"주의력결핍 과잉행동장애는 아동기에 시작하는 발달 문제여서 증상의 일부가 12세 전에 있어야 합니다.","분류체계는 정신장애를 치료하는 의사나 연구자들 간 소통에 도움을 주어":"분류체계가 의사와 연구자 사이의 소통을 돕는다는 문장의 앞부분입니다.","불안과 걱정의 정도, 기간, 빈도는 예상되는 사건이 미치는 실제 영향에 비해 과도하다":"걱정의 크기가 실제로 일어날 일의 영향보다 지나치게 크다는 점이 진단의 요건입니다.","불쾌한 꿈에서 깨면 빠르게 지남력을 회복한다":"악몽에서 깨어나면 곧바로 현실을 알아차리는 점이 야경증과 다릅니다.","불필요한 혼란과 모호함을 감소시켜 준다":"용어와 기준이 통일되어 있으면 같은 증상을 서로 다르게 부르는 혼란이 줄어듭니다.","사람들이 악의적이고 기만적이라는 신념을 가진다":"편집성 성격장애는 타인이 자신을 속이고 해치려 한다는 불신을 바탕에 두고 있습니다.","상담자들과 연구자들이 일관성 있게 공통적인 용어를 사용할 수 있다":"진단 기준이 정해져 있어 상담자와 연구자가 같은 용어를 같은 뜻으로 씁니다.","섭취행동이 사회적 관습, 혹은 문화적 지지를 받지 못한다":"이식증처럼 먹는 행동이 그 사회에서 받아들여지지 않는 경우를 말합니다.","성기능부전, 성도착장애 및 성별 불쾌감":"DSM에서 성별 불쾌감은 성기능부전, 성도착장애와 함께 한 범주로 묶입니다.","성인기까지 지속되어 사회적ㆍ학업적ㆍ직업적 손상을 야기할 수 있다":"아동기에 시작해도 어른이 되도록 이어지면 대인관계와 학업과 직업 생활에 지장을 줍니다.","성형수술을 원하는 경향이 있다":"결함을 고치려고 성형수술을 찾는 일이 많지만 수술 뒤에도 불만이 남는 경우가 흔합니다.","세부 유형의 증상은 각각 최소 6개 영역에서 6개월 동안 부정적 영향이 지속된다":"증상이 6개월 동안 이어지면서 생활에 부정적인 영향을 주는지로 진단을 판단합니다.","스트레스 사건 후 정서적ㆍ행동적 문제들이 3개월 이내에 발생하고, 그 스트레스 요인이 사라지면 6개월 이내로 회복함":"스트레스가 사라지면 반년 안에 회복되는 단기 반응이라는 점이 적응장애의 특징입니다.","신경생물학적 관점에서는 청반핵과 노르에피네프린이 공황장애와 관련되어 있다고 본다":"뇌의 각성 체계인 청반핵과 그 전달물질이 지나치게 활성화되어 공황이 일어난다고 설명합니다.","심각도는 지난 7일중 정신병의 일차 증상 각각에 대하여 가장 심한 정도를 5점 척도로 평가한다":"최근 7일 동안 각 증상이 가장 심했던 정도를 다섯 단계 점수로 매겨 심각도를 정합니다.","심각한 손상을 입히려는 의도로 고의적으로 불을 지른다":"큰 피해를 줄 생각으로 일부러 불을 놓는 것이 품행장애의 재산 파괴 행동입니다.","심각한 질병에 걸려 있거나 걸리는 것에 대해 몰두한다":"질병불안장애는 아프지 않은데도 중병에 걸렸거나 걸릴까 봐 생각에서 벗어나지 못합니다.","심리장애의 유사성과 차이점을 구별하는데 도움을 준다":"분류체계가 있으면 어떤 증상이 같은 장애로 묶이고 어디서 갈리는지 구분하기 쉽습니다.","심리적 치료방법으로 노출 및 반응방지법이 효과적이라고 알려져 있다":"불안한 상황에 직면하되 강박행동을 하지 않고 견디게 하면 불안이 저절로 줄어듭니다.","아동기나 청소년기에 외톨이, 학습부진 등의 양상을 보인다":"조현성 성격장애는 어린 시절부터 또래와 어울리지 못하고 혼자 지내는 모습이 나타납니다.","아동이나 청소년의 경우 성인과 잦은 논쟁을 한다":"어른과 자주 말다툼하는 것이 적대적 반항장애의 행동 양상의 하나입니다.","아동이 보호자로 추정되는 사람과 애착이 없거나 명백하게 미발달되어 있다":"반응성 애착장애는 양육자와의 애착 형성이 거의 이루어지지 않은 상태입니다.","악몽이 발생한 빈도에 따라 심각도를 구분한다":"악몽을 꾸는 횟수가 많을수록 심각도를 높게 분류합니다.","양극성 장애는 모든 연령대에서 발병할 수 있다":"양극성 장애는 청소년기에 흔하지만 어느 연령에서도 처음 나타날 수 있습니다.","양육자와의 애착 외상을 경험한 아동이 낯선 사람을 대상으로 문화적으로 부적절하고 과도하게 친숙한 행동을 보인다":"애착에 상처를 받은 아동이 처음 보는 사람에게도 경계 없이 다가가는 것이 특징입니다.","어떤 연령대에서도 발병할 수 있지만, 아동기에 비해 청소년기에 발병가능성이 높아진다":"우울장애는 어느 나이에도 생기지만 아동기보다 청소년기에 시작할 가능성이 커집니다.","여성은 남성에 비해 주로 부주의 증상을 보인다":"여성은 과잉행동보다 집중이 흐트러지는 부주의 증상이 두드러지는 경향이 있습니다.","예후와 치료의 효과성을 예측하는데 도움이 된다":"진단명이 정해지면 그 장애가 보통 어떻게 진행하고 어떤 치료가 잘 듣는지 가늠할 수 있습니다.","오이디푸스 갈등이 나타나는 발달단계는 남근기이다":"프로이트는 아이가 이성 부모에게 애정을 품는 오이디푸스 갈등을 남근기에 겪는다고 보았습니다.","외상성 사건에 노출된 뒤 3일 이상 1개월 이내로 증상이 지속됨":"급성 스트레스 장애는 충격 사건 직후 3일부터 한 달 이내에 증상이 이어지는 단기 장애입니다.","외상성 사건을 경험한 후, 그 후유증으로 1개월 이상 다양한 부적응적 증상들을 재경험함":"외상 후 한 달이 지나도 사건을 다시 겪는 듯한 증상과 부적응이 계속되면 외상후 스트레스장애입니다.","우울장애와 다른 범주로 분류되어 있다":"DSM에서 양극성 및 관련장애는 우울장애와 별개 범주로 나뉘어 있습니다.","우울한 기분 또는 흥미나 즐거움의 상실 증상이 필수적이다":"주요우울장애를 진단하려면 우울한 기분이나 흥미 상실 가운데 하나는 반드시 있어야 합니다.","원하지 않은 불쾌한 생각이 자꾸 떠올라":"원치 않는 생각이 반복해서 떠오른다는 강박장애 설명의 앞부분입니다.","월경이 시작되기 1주 전에 여러 가지 우울증상이 나타난다":"월경전불쾌감장애는 월경 시작 직전 주에 기분 변동과 우울 증상이 두드러집니다.","유병률은 남성과 여성이 비슷하다":"이 장애는 성별에 따른 발병 비율의 차이가 크지 않다는 내용입니다.","음식을 삼키기 어려운 증상도 포함된다":"신체증상에는 음식을 삼키기 힘든 것처럼 신체 부위에 나타나는 불편감도 들어갑니다.","의학적 상태가 나타나도 질병에 대한 몰두가 과도하거나 부적절하다":"실제 병이 있더라도 그에 비해 걱정이 지나치게 크면 이 장애로 판단합니다.","의학적 진료추구형과 진료회피형으로 세분된다":"질병불안장애는 병원을 자주 찾는 유형과 검사가 두려워 피하는 유형으로 나뉩니다.","이상행동은 주로 고전적 조건형성, 조작적 조건형성, 사회적 모델링의 3가지 학습원리로 설명된다":"행동주의 모형은 두 가지 조건형성과 관찰을 통한 사회적 모델링으로 행동 습득을 설명합니다.","이상행동을 유전적 요인과 뇌의 구조적 결함 등으로 인한 질병으로 본다":"생물학적 모형은 이상행동의 원인을 유전과 뇌 구조 이상 같은 신체적 요인에서 찾습니다.","이상행동을 잘못된 학습의 결과로 본다":"이상행동은 마음의 병이 아니라 부적응적인 행동을 배운 결과라는 관점입니다.","이상행동을 조건형성을 통해 설명한다":"행동주의 모형은 이상행동도 자극과 반응이 짝지어지는 조건형성으로 생긴다고 봅니다.","인식 가능한 스트레스 요인에 대한 반응으로 감정 또는 행동증상이 스트레스 요인이 시작된 지 3개월 이내에 발달한다":"원인이 분명한 스트레스가 시작되고 석 달 안에 정서나 행동 문제가 생기면 적응장애입니다.","일반적으로 발병 연령은 남성이 여성보다 더 빠르다":"강박장애는 남성이 여성보다 이른 나이에 시작하는 경향이 있습니다.","일상생활에 대해서 지나치게 불안해하거나 걱정하는 기간이 최소 6개월 이상이다":"범불안장애는 과도한 걱정이 반년 넘게 이어져야 진단되므로 일시적 걱정과 구분됩니다.","자기 얼굴의 미묘한 비대칭성을 발견한다":"남이 알아채기 힘든 작은 얼굴의 불균형을 자신은 크게 느끼는 증상입니다.","자신의 실수나 잘못된 행동을 자주 남의 탓으로 돌린다":"자기 잘못을 인정하지 않고 책임을 다른 사람에게 미루는 태도를 보입니다.","자신의 해부학적 성별에 대해서는 강한 혐오를 가진다":"타고난 신체의 성적 특징을 심하게 싫어하는 것이 진단 기준에 들어갑니다.","자신이 관심의 초점이 되지 못하는 상황에서 불편감을 느낀다":"남의 주목을 받지 못하면 불안해하는 것은 연극성 성격장애의 특징입니다.","자주 밤늦게까지 집에 들어오지 않는다":"규칙을 어기는 행동의 하나로, 이른 나이에 시작될수록 품행장애의 중요한 기준이 됩니다.","자주 화를 내고 크게 분개한다":"분노와 짜증이 잦고 강하게 터지는 것이 이 장애의 정서적 특징입니다.","장애의 원인은 주요 신경인지장애와 동일하다":"경도 신경인지장애도 주요 신경인지장애와 같은 질환으로 생기며 인지 저하 정도만 다릅니다.","적어도 2년 동안 하루의 대부분 우울한 기분이 있으며, 증상 없는 기간이 2개월 이상 지속되지 않는다":"지속성 우울장애는 우울이 장기간 이어지며 증상이 없는 기간이 2개월을 넘지 않는 만성 상태입니다.","적절한 평가방법과 절차를 계획하기 전에 평가목적을 명료화한다":"무엇을 알려고 평가하는지가 정해져야 그에 맞는 검사 도구와 순서를 고를 수 있습니다.","전형적으로 공포, 불안, 회피는 6개월 이상 지속되어야 한다":"일시적 낯가림과 구분하기 위해 공포와 회피가 반년 넘게 이어지는 기간 기준을 둡니다.","정서적으로 냉담하고 감정표현이 제한되어 있다":"기쁨이나 분노를 거의 드러내지 않고 감정이 평평해 보이는 것이 조현성 성격장애의 정서입니다.","정신건강 전문가 사이에 효과적인 의사소통을 가능하게 한다":"같은 진단명을 쓰면 전문가들이 서로 같은 장애를 떠올리며 대화할 수 있습니다.","정신상태검사에서 환자의 외모와 외현적 행동도 평가한다":"정신상태검사는 말뿐 아니라 옷차림과 태도, 움직임 같은 겉으로 드러난 모습도 관찰 항목입니다.","정신장애에 대한 과학적 연구와 이론개발을 위한 기초를 제공한다":"장애가 일정한 기준으로 구분되어야 연구 대상을 같은 조건으로 모아 이론을 세울 수 있습니다.","정신장애의 공통적 특성과 원인에 대한 연구가 가능해진다":"같은 범주로 묶인 장애들을 비교하여 공통 증상이나 원인을 찾는 연구를 할 수 있습니다.","제Ⅰ형 양극성 장애, 제Ⅱ형 양극성 장애, 순환성장애가 있다":"양극성 및 관련장애에는 이 세 가지 하위 유형이 있고 조증 삽화가 있으면 첫째 유형입니다.","조증이나 주요우울 삽화가 일어난다면 망상 지속 기간에 비해 상대적으로 짧다":"기분 삽화가 있더라도 망상이 이어진 기간보다 짧아야 기분장애가 아닌 망상장애로 봅니다.","조현병 스펙트럼장애로 분류된다":"조현형 성격장애는 성격장애이면서 조현병과 같은 스펙트럼 범주에 함께 묶입니다.","주로 생존이나 안전을 위협하는 내용과 관련된 악몽을 꾼다":"악몽의 내용은 대개 목숨이나 신변 안전이 위험해지는 장면입니다.","주요 기분(주요우울 또는 조증)삽화 없이 존재하는 2주 이상의 망상이나 환각이 있다":"조현정동장애에서 기분 삽화가 없는 시기에도 망상이나 환각이 2주 넘게 이어지는 기간을 나타냅니다.","주요 특징은 만성적인 고도의 지속적 과민성이다":"파괴적 기분조절부전장애는 아동에서 심한 짜증과 폭발이 지속되는 것이 중심입니다.","주의력결핍 과잉행동장애가 있는 아동은 품행장애 등 공존장애를 가지고 있는 경우가 있다":"이 장애의 아동은 품행장애 같은 다른 장애를 함께 지니는 일이 적지 않습니다.","지나치게 인상적이고 세밀함이 결여된 형태의 언어를 사용한다":"말은 화려하고 인상적이지만 구체적인 내용이 부족한 것이 연극성 성격장애의 언어 특징입니다.","직업이나 건강, 재정, 사소한 문제와 같은 일상생활 환경에 대해 걱정한다":"걱정의 대상이 일, 건강, 돈, 소소한 일처럼 평범한 일상사라는 설명입니다.","진단하기 위해서는 조증 삽화 진단기준이 충족되어야 한다":"양극성장애 중 첫째 유형은 우울 삽화만으로는 안 되고 조증 삽화 기준을 채워야 진단합니다.","청소년기 후기나 성인기 초기에 유병률이 가장 높다":"악몽장애는 청소년 후반에서 성인 초반 시기에 가장 흔합니다.","최소 6개월 기간으로 진단기준의 증상들이 나타나야 한다":"성별 불쾌감은 증상이 반년 이상 이어져야 진단 기준을 채웁니다.","축적된 연구결과와 임상적 지식을 체계적으로 정리 및 전달할 수 있다":"장애별로 분류해 두면 쌓인 연구 결과와 임상 경험을 범주에 맞게 정돈해 전할 수 있습니다.","충격적인 외상사건을 경험한 후 그 후유증으로 1개월 이상 반복적이고 불수의적이며 침습적으로 외상사건이 떠오르는 고통스러운 증상을 경험한다":"원하지 않는데도 외상 장면이 머릿속에 자꾸 밀려들어 한 달 넘게 괴로운 상태입니다.","충분한 근거 없이 타인이 자신을 착취하고 해를 끼친다고 의심한다":"증거가 부족한데도 남이 이용하거나 해치려 한다고 의심하는 것이 편집성 성격장애의 핵심입니다.","치료에는 체계적 둔감법이 있다":"행동주의의 대표 치료로, 약한 불안 자극부터 이완하며 노출시켜 불안 반응을 없앱니다.","치료에서는 상담자가 방어적으로 반응하기보다 솔직하고 일관성 있는 태도로 신뢰감을 주는 것이 중요하다":"의심 많은 내담자는 상담자의 말과 행동이 한결같을 때 믿음을 갖기 시작합니다.","타인과의 관계를 실제보다 더 가깝다고 생각해 거의 모든 지인을 친한 친구라고 표현한다":"실제 친밀도보다 관계를 부풀려서 보는 것이 연극성 성격장애의 특징입니다.","타인의 부정적 평가를 두려워한다":"남들이 자신을 나쁘게 볼까 두려워하는 것이 사회불안장애의 중심 공포입니다.","타인의 정서적 학대 및 무시와는 무관하다":"신체이형장애의 발병 원인을 타인의 정서적 학대나 무시에서 찾지 않는다는 내용입니다.","타인의 칭찬이나 비난에 무관심하다":"조현성 성격장애는 다른 사람의 평가에 거의 반응하지 않는 무관심을 보입니다.","파괴적, 충동조절 및 품행장애":"적대적 반항장애는 DSM에서 파괴적, 충동조절 및 품행장애 범주에 속합니다.","표준화된 신경심리검사에 의해서 경도의 인지 손상이 입증될 수 있다":"기억과 주의를 재는 표준 검사에서 가벼운 인지 손상이 점수로 확인될 수 있습니다.","하나 이상의 사회적 상황에서 공포와 불안을 보인다":"발표나 대화 같은 사회적 상황 중 하나만 있어도 공포와 불안이 나타나면 해당합니다.","하나 이상의 신체 결함에 과도하게 집착한다":"신체이형장애는 남들이 보기엔 미미하거나 없는 외모의 결함에 지나치게 매달립니다.","하나 이상의 인지 영역에서 이전에 비해 경도의 저하가 나타난다":"기억이나 언어 같은 인지 영역 중 하나라도 예전보다 가볍게 떨어지면 해당합니다.","핵심적 특징은 수많은 사건이나 활동에 대한 과도한 불안과 걱정이다":"범불안장애는 특정 대상 하나가 아니라 여러 일에 대해 걱정이 번지는 것이 핵심입니다.","행동문제가 2가지 이상의 다른 환경에서 나타난다":"한 장소에서만 문제가 생기면 그 환경의 영향일 수 있어 여러 환경에서 나타나야 합니다.","후기 청소년이나 성인의 경우에 세부 유형의 증상이 5개이어도 해당된다":"나이가 많은 사람에게는 진단 기준의 증상 수를 5개로 낮추어 적용합니다.","훔치기 직전에 고조되는 긴장감이 나타난다":"도벽에서는 훔치기 직전에 긴장이 높아지고 행위 뒤에 긴장이 풀리는 경험을 합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
